-- Autostart
hl.on("hyprland.start", function()
    -- WAYLAND_DISPLAY/XDG_CURRENT_DESKTOP ya los exporta Hyprland a D-Bus y systemd al arrancar
    -- Portales: los arranca systemd (xdg-desktop-portal*.service); FixPortals.sh los mataba y systemd los relanzaba
    hl.exec_cmd(scriptsDir .. "/Polkit.sh")
    -- Fondo: vídeo si WallpaperSelect.sh dejó uno en UserConfigs/LiveWallpaper (requiere mpvpaper);
    -- si no, awww-daemon, que ya restaura el último fondo desde su caché
    local f = io.open(Paths.userConfigs .. "/LiveWallpaper", "r")
    local video = f and (f:read("l") or ""):match("^%s*(.-)%s*$") or ""
    if f then f:close() end
    if video ~= "" then
        hl.exec_cmd("mpvpaper '*' -o 'load-scripts=no no-audio --loop' '" .. video .. "'")
    else
        hl.exec_cmd("awww-daemon --format xrgb")
    end
    hl.exec_cmd("waybar")
    -- swaync no se lanza aquí: lo activa D-Bus (swaync.service) en cuanto waybar o una app lo piden.
    -- Lanzarlo a mano competía con esa activación y dejaba fallos "already running" en el journal.
    hl.exec_cmd("hypridle")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd(scriptsDir .. "/Hyprsunset.sh init")
    -- Overview (qs -c overview): ya no se arranca aquí; SUPER+A lo lanza la primera vez (~150 ms) y ahorra ~300 MB
    hl.exec_cmd("cliphist wipe")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)
